package com.crejaud.chanced;

import lombok.Builder;
import lombok.Value;

/** One attack that landed on the local player this tick, with what it could have hit. */
@Value
@Builder
class Attack
{
	/** Display name of the attacker. */
	String source;
	AttackStyle style;
	/** Max hit for {@link #style}, before prayer. */
	int max;
	/** Whether the correct protection prayer was up for this attack. */
	boolean prayed;
	/** Max hit through the correct protection prayer (NPCs); 0 when the prayer blocks it fully. */
	@Builder.Default
	int prayedMax = 0;
	/** The attacker's typeless/special max, or -1 when it has none. */
	@Builder.Default
	int specialMax = -1;
	/** Wiki label of that special, e.g. "Prayer smash" or "Rockfall". */
	@Builder.Default
	String specialName = "Special";
	/** A player attacker: prayer reduces by 40% instead of blocking, and the max is an estimate. */
	boolean player;
}

package com.crejaud.chanced;

/** What an attack animation's name says about its style. UNKNOWN still marks an attack. */
enum AttackHint
{
	MELEE,
	RANGED,
	MAGIC,
	SPECIAL,
	UNKNOWN;

	AttackStyle toStyle()
	{
		switch (this)
		{
			case MELEE:
				return AttackStyle.MELEE;
			case RANGED:
				return AttackStyle.RANGED;
			case MAGIC:
				return AttackStyle.MAGIC;
			case SPECIAL:
				return AttackStyle.SPECIAL;
			default:
				return null;
		}
	}
}

package com.crejaud.chanced;

import lombok.Getter;
import lombok.RequiredArgsConstructor;
import net.runelite.api.Prayer;

/** How a hit is dealt. SPECIAL covers typeless and wiki-labelled special attacks. */
@Getter
@RequiredArgsConstructor
enum AttackStyle
{
	MELEE("Melee", Prayer.PROTECT_FROM_MELEE),
	RANGED("Ranged", Prayer.PROTECT_FROM_MISSILES),
	MAGIC("Magic", Prayer.PROTECT_FROM_MAGIC),
	SPECIAL("Special", null);

	private final String displayName;
	/** Protection prayer that blocks this style, or null when none does. */
	private final Prayer protection;

	boolean isNormal()
	{
		return this != SPECIAL;
	}
}

package com.crejaud.chanced;

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.HashMap;
import java.util.Map;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;

/**
 * Attack style implied by each NPC attack animation and projectile, from the bundled
 * {@code attack_styles.txt} snapshot (generated from RuneLite's gameval names by
 * {@code scripts/generate_attack_styles.py}). Ids missing from it fall back to the NPC's
 * wiki attack styles.
 */
@Slf4j
@Singleton
class AttackStyleTable
{
	static final String RESOURCE = "attack_styles.txt";
	/** Line fields: {@code a|p id STYLE [name]}. */
	private static final int KIND_FIELD = 0;
	private static final int ID_FIELD = 1;
	private static final int STYLE_FIELD = 2;

	private final Map<Integer, AttackHint> animations = new HashMap<>();
	private final Map<Integer, AttackStyle> projectiles = new HashMap<>();

	AttackStyleTable()
	{
		try (InputStream in = AttackStyleTable.class.getResourceAsStream(RESOURCE))
		{
			if (in == null)
			{
				log.warn("Chanced: {} is missing", RESOURCE);
				return;
			}
			load(new BufferedReader(new InputStreamReader(in, StandardCharsets.UTF_8)));
		}
		catch (IOException e)
		{
			log.warn("Chanced: could not read {}", RESOURCE, e);
		}
	}

	/** Hint for an attack animation, or null when the animation is not a known attack. */
	AttackHint animation(int id)
	{
		return animations.get(id);
	}

	/** Style of a projectile, or null when its name does not say. */
	AttackStyle projectile(int id)
	{
		return projectiles.get(id);
	}

	int animationCount()
	{
		return animations.size();
	}

	int projectileCount()
	{
		return projectiles.size();
	}

	private void load(BufferedReader reader) throws IOException
	{
		String line;
		while ((line = reader.readLine()) != null)
		{
			if (line.isEmpty() || line.charAt(0) == '#')
			{
				continue;
			}
			String[] f = line.split(" ");
			if (f.length <= STYLE_FIELD)
			{
				continue;
			}
			try
			{
				int id = Integer.parseInt(f[ID_FIELD]);
				if ("a".equals(f[KIND_FIELD]))
				{
					animations.put(id, AttackHint.valueOf(f[STYLE_FIELD]));
				}
				else if ("p".equals(f[KIND_FIELD]))
				{
					projectiles.put(id, AttackStyle.valueOf(f[STYLE_FIELD]));
				}
			}
			catch (IllegalArgumentException e)
			{
				// unknown style name; skip the line
			}
		}
	}
}

package com.crejaud.chanced;

import java.util.IdentityHashMap;
import java.util.List;
import java.util.Map;

/**
 * Decides whether a tick's hits could have killed the player. HP at the hit is HP after the
 * tick plus the damage taken, so food eaten on the tick counts.
 */
final class ChanceCalculator
{
	static final int PVP_PRAYER_PERCENT = 60;
	private static final int PERCENT = 100;

	private ChanceCalculator()
	{
	}

	/**
	 * @param hits    every damage hitsplat on the player this tick
	 * @param hpAfter hitpoints after the tick
	 * @return the verdict, or null when the tick was not a chance
	 */
	static Verdict evaluate(List<Hit> hits, int hpAfter)
	{
		if (hits.isEmpty() || hpAfter <= 0)
		{
			return null;
		}

		int damage = 0;
		int potential = 0;
		Map<Attack, Integer> byAttack = new IdentityHashMap<>();
		for (Hit hit : hits)
		{
			damage += hit.getDamage();
			if (hit.getAttack() != null)
			{
				byAttack.merge(hit.getAttack(), hit.getDamage(), Integer::sum);
			}
			else
			{
				// Damage over time and hits with no known source count at the damage dealt.
				potential += hit.getDamage();
			}
		}
		int hpBefore = hpAfter + damage;

		Attack worst = null;
		int worstMax = -1;
		String worstStyle = null;
		boolean estimate = false;
		for (Map.Entry<Attack, Integer> e : byAttack.entrySet())
		{
			Attack attack = e.getKey();
			int dealt = e.getValue();
			int max = effectiveMax(attack, dealt);
			potential += max;
			estimate |= attack.isPlayer();
			if (max > worstMax)
			{
				worst = attack;
				worstMax = max;
				worstStyle = styleShown(attack, dealt);
			}
		}

		if (worst == null || potential < hpBefore)
		{
			return null;
		}
		return new Verdict(worst.getSource(), worstStyle, potential, damage, hpBefore, hpAfter, estimate);
	}

	/** What one attack could have hit, given it actually dealt {@code dealt}. */
	static int effectiveMax(Attack attack, int dealt)
	{
		int max = attack.getMax();
		if (attack.isPlayer())
		{
			if (attack.isPrayed())
			{
				max = max * PVP_PRAYER_PERCENT / PERCENT;
			}
		}
		else if (attack.getStyle().isNormal() && attack.isPrayed())
		{
			// The right prayer blocks it down to prayedMax. A hit through it anyway is the
			// NPC's special (prayer smash) when it has one; otherwise the prayer only reduces
			// this attack, by an amount the wiki does not give, so count the damage dealt.
			max = throughPrayer(attack, dealt) && attack.getSpecialMax() > 0
				? attack.getSpecialMax()
				: attack.getPrayedMax();
		}
		return Math.max(max, dealt);
	}

	private static boolean throughPrayer(Attack attack, int dealt)
	{
		return dealt > attack.getPrayedMax();
	}

	private static String styleShown(Attack attack, int dealt)
	{
		if (!attack.isPlayer() && attack.getStyle().isNormal() && attack.isPrayed() && attack.getSpecialMax() > 0
			&& throughPrayer(attack, dealt))
		{
			return attack.getSpecialName();
		}
		if (attack.getStyle() == AttackStyle.SPECIAL)
		{
			return attack.getSpecialName();
		}
		return attack.getStyle().getDisplayName();
	}
}

