package com.crejaud.chanced;

import com.google.common.collect.ImmutableMap;
import com.google.common.collect.ImmutableSet;
import java.util.Map;
import java.util.Set;
import net.runelite.api.Player;
import net.runelite.api.PlayerComposition;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.NpcID;
import net.runelite.api.kit.KitType;

/**
 * The Gauntlet's Hunllef: its max hit depends on the crystal armour worn, its ranged and magic
 * attacks hit through the correct protection prayer, and its tornadoes and floor tiles hit with
 * no attack to see. Numbers are the OSRS Wiki's tables for full armour sets; mixed sets are
 * interpolated by total armour tier.
 */
final class HunllefRules
{
	private static final Set<Integer> CORRUPTED = ImmutableSet.of(
		NpcID.CRYSTAL_HUNLLEF_MELEE_HM, NpcID.CRYSTAL_HUNLLEF_RANGED_HM, NpcID.CRYSTAL_HUNLLEF_MAGIC_HM);
	private static final Set<Integer> CRYSTALLINE = ImmutableSet.of(
		NpcID.CRYSTAL_HUNLLEF_MELEE, NpcID.CRYSTAL_HUNLLEF_RANGED, NpcID.CRYSTAL_HUNLLEF_MAGIC,
		NpcID.LEAGUE_6_CRYSTAL_HUNLLEF_MELEE);

	/** Max hits for no armour, full T1, full T2 and full T3. */
	private static final int[] CORRUPTED_UNPRAYED = {68, 55, 45, 35};
	private static final int[] CORRUPTED_PRAYED = {16, 13, 10, 8};
	private static final int[] CORRUPTED_TORNADO = {30, 25, 20, 15};
	private static final int[] CRYSTALLINE_PRAYED = {12, 10, 8, 6};
	/** The wiki lists only "50+" unprayed; scaled from the Corrupted table by the prayed ratio. */
	private static final int[] CRYSTALLINE_UNPRAYED = {51, 41, 34, 26};
	private static final int[] CRYSTALLINE_TORNADO = {20, 16, 13, 10};

	private static final int T1 = 1;
	private static final int T2 = 2;
	private static final int T3 = 3;
	/** Helm, body and legs. */
	private static final int PIECES = 3;
	/** Full T3: the top of the armour tables. */
	private static final int MAX_POINTS = PIECES * T3;

	private static final Map<Integer, Integer> ARMOUR_TIER = ImmutableMap.<Integer, Integer>builder()
		.put(ItemID.GAUNTLET_HELMET_T1, T1).put(ItemID.GAUNTLET_HELMET_T2, T2).put(ItemID.GAUNTLET_HELMET_T3, T3)
		.put(ItemID.GAUNTLET_CHESTPLATE_T1, T1).put(ItemID.GAUNTLET_CHESTPLATE_T2, T2)
		.put(ItemID.GAUNTLET_CHESTPLATE_T3, T3)
		.put(ItemID.GAUNTLET_PLATELEGS_T1, T1).put(ItemID.GAUNTLET_PLATELEGS_T2, T2)
		.put(ItemID.GAUNTLET_PLATELEGS_T3, T3)
		.put(ItemID.GAUNTLET_HELMET_T1_HM, T1).put(ItemID.GAUNTLET_HELMET_T2_HM, T2)
		.put(ItemID.GAUNTLET_HELMET_T3_HM, T3)
		.put(ItemID.GAUNTLET_CHESTPLATE_T1_HM, T1).put(ItemID.GAUNTLET_CHESTPLATE_T2_HM, T2)
		.put(ItemID.GAUNTLET_CHESTPLATE_T3_HM, T3)
		.put(ItemID.GAUNTLET_PLATELEGS_T1_HM, T1).put(ItemID.GAUNTLET_PLATELEGS_T2_HM, T2)
		.put(ItemID.GAUNTLET_PLATELEGS_T3_HM, T3)
		.build();

	private HunllefRules()
	{
	}

	static boolean isHunllef(int npcId)
	{
		return CORRUPTED.contains(npcId) || CRYSTALLINE.contains(npcId);
	}

	/** Sum of the helm, body and legs tiers (0 to 9). */
	static int armourPoints(Player player)
	{
		PlayerComposition comp = player.getPlayerComposition();
		if (comp == null)
		{
			return 0;
		}
		int points = 0;
		for (KitType slot : new KitType[]{KitType.HEAD, KitType.TORSO, KitType.LEGS})
		{
			points += ARMOUR_TIER.getOrDefault(comp.getEquipmentId(slot), 0);
		}
		return points;
	}

	/**
	 * The Hunllef attack that landed.
	 *
	 * @param style        style of a seen attack, or SPECIAL for a tornado or floor hit
	 * @param prayed       whether the correct protection prayer was up
	 * @param armourPoints {@link #armourPoints} of the player
	 */
	static Attack attack(int npcId, String name, AttackStyle style, boolean prayed, int armourPoints)
	{
		boolean corrupted = CORRUPTED.contains(npcId);
		if (style == AttackStyle.SPECIAL)
		{
			int max = scaled(corrupted ? CORRUPTED_TORNADO : CRYSTALLINE_TORNADO, armourPoints);
			return Attack.builder().source(name).style(AttackStyle.SPECIAL).max(max)
				.specialName("Tornado or floor").build();
		}
		return Attack.builder()
			.source(name)
			.style(style)
			.max(scaled(corrupted ? CORRUPTED_UNPRAYED : CRYSTALLINE_UNPRAYED, armourPoints))
			.prayed(prayed)
			.prayedMax(scaled(corrupted ? CORRUPTED_PRAYED : CRYSTALLINE_PRAYED, armourPoints))
			.build();
	}

	/** Interpolates a full-set table (no armour, full T1, T2, T3) at any point total. */
	static int scaled(int[] table, int points)
	{
		int p = Math.max(0, Math.min(MAX_POINTS, points));
		int i = Math.min(p / PIECES, table.length - 1 - 1);
		int lo = table[i];
		int hi = table[i + 1];
		int rem = p - i * PIECES;
		return lo - ((lo - hi) * rem) / PIECES;
	}
}

package com.crejaud.chanced;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import java.io.IOException;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.time.Duration;
import java.time.Instant;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.ScheduledExecutorService;
import java.util.function.Consumer;
import javax.annotation.Nonnull;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.util.Filepath;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.HttpUrl;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.ResponseBody;

/**
 * Max hits per NPC id from the OSRS Wiki {@code infobox_monster} bucket. Downloaded once,
 * kept in memory and cached on disk for a day.
 */
@Slf4j
@Singleton
class MaxHitRepository
{
	static final String CACHE_FILE = "max-hits-v2.json";
	private static final Duration CACHE_TTL = Duration.ofHours(24);
	private static final int PAGE_SIZE = 5000;
	private static final HttpUrl WIKI_API = HttpUrl.get("https://oldschool.runescape.wiki/api.php");

	private final OkHttpClient httpClient;
	private final Gson gson;
	private final ScheduledExecutorService executor;
	/** The wiki page request in flight, cancelled when the plugin stops. */
	private volatile Call inFlight;

	private volatile Map<Integer, MonsterInfo> monsters = Collections.emptyMap();

	@Inject
	MaxHitRepository(OkHttpClient httpClient, Gson gson, ScheduledExecutorService executor)
	{
		this.httpClient = httpClient;
		this.gson = gson;
		this.executor = executor;
	}

	/** Max hits for an NPC id, or null when the wiki has none (or data is not loaded yet). */
	MonsterInfo get(int npcId)
	{
		return monsters.get(npcId);
	}

	int size()
	{
		return monsters.size();
	}

	/** Drops the loaded max hits and cancels a download in flight. */
	void clear()
	{
		Call call = inFlight;
		if (call != null)
		{
			call.cancel();
		}
		monsters = Collections.emptyMap();
	}

	/**
	 * Loads from the disk cache when it is fresh, otherwise downloads. Runs off the client
	 * thread; {@code done} receives a short status message.
	 */
	void load(Filepath dir, boolean force, Consumer<String> done)
	{
		executor.execute(() ->
		{
			Filepath cache = dir.joinSegment(CACHE_FILE);
			if (!force && readCache(cache))
			{
				done.accept("Loaded " + monsters.size() + " max hits from cache");
				return;
			}
			download(cache, new JsonArray(), 0, done);
		});
	}

	private boolean readCache(Filepath cache)
	{
		try
		{
			if (!cache.exists()
				|| cache.getLastModifiedTime().toInstant().isBefore(Instant.now().minus(CACHE_TTL)))
			{
				return false;
			}
			try (Reader reader = cache.openReader())
			{
				JsonObject response = gson.fromJson(reader, JsonObject.class);
				Map<Integer, MonsterInfo> parsed = WikiMonsterParser.parseResponse(response);
				if (parsed.isEmpty())
				{
					return false;
				}
				monsters = parsed;
				return true;
			}
		}
		catch (IOException | RuntimeException e)
		{
			log.debug("Could not read max hit cache", e);
			return false;
		}
	}

	private void download(Filepath cache, JsonArray rows, int offset, Consumer<String> done)
	{
		HttpUrl url = WIKI_API.newBuilder()
			.addQueryParameter("action", "bucket")
			.addQueryParameter("format", "json")
			.addQueryParameter("query", "bucket('infobox_monster')"
				+ ".select('id','name','max_hit','attack_style')"
				+ ".limit(" + PAGE_SIZE + ").offset(" + offset + ").run()")
			.build();
		Request request = new Request.Builder().url(url).build();
		Call pageCall = httpClient.newCall(request);
		inFlight = pageCall;
		pageCall.enqueue(new Callback()
		{
			@Override
			public void onFailure(@Nonnull Call call, @Nonnull IOException e)
			{
				if (call.isCanceled())
				{
					return;
				}
				log.debug("Max hit download failed", e);
				done.accept("Could not download max hits from the OSRS Wiki");
			}

			@Override
			public void onResponse(@Nonnull Call call, @Nonnull Response response)
			{
				try (ResponseBody body = response.body())
				{
					if (call.isCanceled())
					{
						return;
					}
					if (!response.isSuccessful() || body == null)
					{
						done.accept("OSRS Wiki returned HTTP " + response.code());
						return;
					}
					JsonObject page = gson.fromJson(body.charStream(), JsonObject.class);
					JsonArray pageRows = page.getAsJsonArray("bucket");
					if (pageRows == null)
					{
						done.accept("OSRS Wiki returned no monster data");
						return;
					}
					rows.addAll(pageRows);
					if (pageRows.size() >= PAGE_SIZE)
					{
						download(cache, rows, offset + PAGE_SIZE, done);
						return;
					}
					finish(cache, rows, done);
				}
				catch (RuntimeException e)
				{
					log.debug("Bad max hit response", e);
					done.accept("Could not read OSRS Wiki monster data");
				}
			}
		});
	}

	private void finish(Filepath cache, JsonArray rows, Consumer<String> done)
	{
		JsonObject all = new JsonObject();
		all.add("bucket", rows);
		Map<Integer, MonsterInfo> parsed = new HashMap<>();
		WikiMonsterParser.parseRows(rows, parsed);
		monsters = parsed;
		try
		{
			cache.getParent().createDirectories();
			cache.write(gson.toJson(all).getBytes(StandardCharsets.UTF_8));
		}
		catch (IOException e)
		{
			log.debug("Could not write max hit cache", e);
		}
		done.accept("Downloaded " + parsed.size() + " max hits from the OSRS Wiki");
	}
}

package com.crejaud.chanced;

import java.util.EnumMap;
import java.util.Map;
import lombok.Getter;

/** One NPC id's max hit per attack style, merged from every wiki infobox that lists the id. */
@Getter
final class MonsterInfo
{
	private final String name;
	private final Map<AttackStyle, Integer> maxHits = new EnumMap<>(AttackStyle.class);
	/** Wiki label of the biggest special, e.g. "Rockfall". */
	private String specialName = AttackStyle.SPECIAL.getDisplayName();

	MonsterInfo(String name)
	{
		this.name = name;
	}

	/** Records a max hit, keeping the higher value when the style is already known. */
	void put(AttackStyle style, int max)
	{
		maxHits.merge(style, max, Math::max);
	}

	/** Records a special max hit with its wiki label. */
	void putSpecial(int max, String label)
	{
		if (max > max(AttackStyle.SPECIAL) && label != null && !label.isEmpty())
		{
			specialName = label;
		}
		put(AttackStyle.SPECIAL, max);
	}

	void merge(MonsterInfo other)
	{
		if (other.has(AttackStyle.SPECIAL))
		{
			putSpecial(other.max(AttackStyle.SPECIAL), other.specialName);
		}
		other.maxHits.forEach((style, max) ->
		{
			if (style.isNormal())
			{
				put(style, max);
			}
		});
	}

	/** Max hit for a style, or -1 when the wiki lists none. */
	int max(AttackStyle style)
	{
		return maxHits.getOrDefault(style, -1);
	}

	boolean has(AttackStyle style)
	{
		return maxHits.containsKey(style);
	}

	boolean hasNormalStyle()
	{
		for (AttackStyle style : maxHits.keySet())
		{
			if (style.isNormal())
			{
				return true;
			}
		}
		return false;
	}
}

package com.crejaud.chanced;

import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Player;
import net.runelite.api.PlayerComposition;
import net.runelite.api.kit.KitType;
import net.runelite.client.game.ItemEquipmentStats;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.ItemStats;

/**
 * Worst-case max hit of another player from their visible gear, assuming 99s, the best
 * boosting potion and prayer, and an assumed ring and ammo (neither is visible).
 */
@Singleton
class PvpEstimator
{
	/** 99 + super combat / ranging potion boost. */
	private static final int BOOSTED_STRENGTH = 118;
	private static final int BOOSTED_RANGED = 112;
	/** Piety / Rigour multiplier, as a percent. */
	private static final int PRAYER_BONUS = 123;
	/** Ice Barrage, the biggest common PvP spell base. */
	private static final int MAGIC_BASE = 30;
	private static final int PERCENT = 100;
	/** Max hit formula: +8 to the effective level, +3 more for the aggressive stance. */
	private static final int EFFECTIVE_LEVEL_BONUS = 8;
	private static final int AGGRESSIVE_STANCE = 3;
	private static final int STRENGTH_OFFSET = 64;
	private static final int MAX_HIT_DIVISOR = 640;
	/** Adds half the divisor so the division rounds to nearest. */
	private static final int ROUND_HALF = MAX_HIT_DIVISOR / 2;
	/** Rings and ammo are not visible on other players: assume a berserker ring and dragon bolts. */
	static final int RING_STRENGTH = 8;
	static final int AMMO_STRENGTH = 122;
	/** Room for special attacks above the normal max. */
	static final int SPEC_MARGIN_PERCENT = 25;

	private final ItemManager itemManager;

	@Inject
	PvpEstimator(ItemManager itemManager)
	{
		this.itemManager = itemManager;
	}

	/** Totals of a player's visible equipment. */
	static final class Gear
	{
		int str;
		int rstr;
		float mdmg;
		int weaponMelee;
		int weaponRanged;
		int weaponMagic;
		int weaponRstr;
	}

	Gear gear(Player player)
	{
		Gear gear = new Gear();
		PlayerComposition comp = player.getPlayerComposition();
		if (comp == null)
		{
			return gear;
		}
		for (KitType slot : KitType.values())
		{
			int itemId = comp.getEquipmentId(slot);
			if (itemId <= 0)
			{
				continue;
			}
			ItemStats stats = itemManager.getItemStats(itemId);
			if (stats == null || stats.getEquipment() == null)
			{
				continue;
			}
			ItemEquipmentStats e = stats.getEquipment();
			gear.str += e.getStr();
			gear.rstr += e.getRstr();
			gear.mdmg += e.getMdmg();
			if (slot == KitType.WEAPON)
			{
				gear.weaponMelee = Math.max(e.getAstab(), Math.max(e.getAslash(), e.getAcrush()));
				gear.weaponRanged = e.getArange();
				gear.weaponMagic = e.getAmagic();
				gear.weaponRstr = e.getRstr();
			}
		}
		return gear;
	}

	/** Style the weapon is built for. */
	static AttackStyle weaponStyle(Gear gear)
	{
		if (gear.weaponMagic > gear.weaponMelee && gear.weaponMagic > gear.weaponRanged)
		{
			return AttackStyle.MAGIC;
		}
		if (gear.weaponRanged > gear.weaponMelee || gear.weaponRstr > 0)
		{
			return AttackStyle.RANGED;
		}
		return AttackStyle.MELEE;
	}

	/** Estimated max hit for a style, with a margin for special attacks. */
	static int maxHit(Gear gear, AttackStyle style)
	{
		return maxHit(gear, style, RING_STRENGTH, AMMO_STRENGTH, SPEC_MARGIN_PERCENT);
	}

	static int maxHit(Gear gear, AttackStyle style, int ringStr, int ammoRstr, int specMarginPercent)
	{
		int max;
		switch (style)
		{
			case RANGED:
			{
				int effective = BOOSTED_RANGED * PRAYER_BONUS / PERCENT + EFFECTIVE_LEVEL_BONUS;
				// Thrown weapons and blowpipes carry their own ranged strength.
				int rstr = gear.rstr + (gear.weaponRstr > 0 ? 0 : ammoRstr);
				max = maxFromEffective(effective, rstr);
				break;
			}
			case MAGIC:
				max = (int) (MAGIC_BASE * (1 + gear.mdmg / PERCENT));
				break;
			default:
			{
				int effective = BOOSTED_STRENGTH * PRAYER_BONUS / PERCENT + AGGRESSIVE_STANCE + EFFECTIVE_LEVEL_BONUS;
				max = maxFromEffective(effective, gear.str + ringStr);
				break;
			}
		}
		return max * (PERCENT + specMarginPercent) / PERCENT;
	}

	/** The game's max hit formula: effective level times (strength bonus + 64) over 640, rounded. */
	private static int maxFromEffective(int effectiveLevel, int strengthBonus)
	{
		return (effectiveLevel * (strengthBonus + STRENGTH_OFFSET) + ROUND_HALF) / MAX_HIT_DIVISOR;
	}
}

