package com.crejaud.chanced;

import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.util.ArrayList;
import java.util.EnumSet;
import java.util.HashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Parses rows of the OSRS Wiki {@code infobox_monster} bucket into max hits per NPC id.
 *
 * <p>The wiki's {@code max_hit} field is free text: "13 (Melee)", "7x2 (Magic)", "7+6",
 * "50/60 (Melee)", "30-37 (Melee)", several entries split by {@code <br>}. An unlabelled
 * number applies to every style in {@code attack_style}. A label that names no normal style
 * (Rockfall, Dragonfire, special attack) is a special: typeless, not blocked by prayer.
 */
final class WikiMonsterParser
{
	private static final Pattern SPLIT = Pattern.compile("<br\\s*/?>|\\n|\\*");
	private static final Pattern TAGS = Pattern.compile("<[^>]*>|\u007f'\"`UNIQ--[^`]*`\"'\u007f|&[a-z]+;");
	/** Leading number, with an optional xN multiplier or +N / /N / -N follow-ups. */
	private static final Pattern NUMBER = Pattern.compile(
		"^~?(\\d+)\\s*(?:[x×]\\s*(\\d+)|((?:\\s*[+/-]\\s*\\d+)+))?\\+?\\s*(.*)$");
	private static final Pattern FOLLOW = Pattern.compile("([+/-])\\s*(\\d+)");
	/** {@link #NUMBER} groups after the number itself: the multiplier, the follow-ups and the rest. */
	private static final int MULTIPLIER = 2;
	private static final int FOLLOW_UPS = 3;
	private static final int REST = 4;
	/** {@link #FOLLOW} group of the follow-up's value. */
	private static final int FOLLOW_VALUE = 2;
	private static final Pattern LABEL = Pattern.compile("\\(([^)]*)\\)?");

	private WikiMonsterParser()
	{
	}

	/** Parses a bucket API response body ({@code {"bucket": [...]}}). */
	static Map<Integer, MonsterInfo> parseResponse(JsonObject response)
	{
		Map<Integer, MonsterInfo> out = new HashMap<>();
		JsonArray rows = response.getAsJsonArray("bucket");
		if (rows != null)
		{
			parseRows(rows, out);
		}
		return out;
	}

	static void parseRows(JsonArray rows, Map<Integer, MonsterInfo> out)
	{
		for (JsonElement el : rows)
		{
			if (!el.isJsonObject())
			{
				continue;
			}
			JsonObject row = el.getAsJsonObject();
			String name = row.has("name") ? row.get("name").getAsString() : "Unknown";
			MonsterInfo info = parse(name, strings(row, "max_hit"), strings(row, "attack_style"));
			if (info.getMaxHits().isEmpty())
			{
				continue;
			}
			for (String id : strings(row, "id"))
			{
				try
				{
					int npcId = Integer.parseInt(id.trim());
					out.computeIfAbsent(npcId, k -> new MonsterInfo(name)).merge(info);
				}
				catch (NumberFormatException ignored)
				{
					// some rows list non-numeric ids; skip them
				}
			}
		}
	}

	static MonsterInfo parse(String name, List<String> maxHits, List<String> attackStyles)
	{
		Set<AttackStyle> defaults = EnumSet.noneOf(AttackStyle.class);
		for (String style : attackStyles)
		{
			defaults.addAll(stylesOf(style, false));
		}
		if (defaults.isEmpty())
		{
			defaults = EnumSet.of(AttackStyle.MELEE, AttackStyle.RANGED, AttackStyle.MAGIC);
		}

		MonsterInfo info = new MonsterInfo(name);
		for (String field : maxHits)
		{
			for (String part : SPLIT.split(field))
			{
				parsePart(TAGS.matcher(part).replaceAll(" ").trim(), defaults, info);
			}
		}
		return info;
	}

	private static void parsePart(String part, Set<AttackStyle> defaults, MonsterInfo info)
	{
		Matcher m = NUMBER.matcher(part);
		if (!m.matches())
		{
			return;
		}
		int value = Integer.parseInt(m.group(1));
		if (m.group(MULTIPLIER) != null)
		{
			value *= Integer.parseInt(m.group(MULTIPLIER));
		}
		else if (m.group(FOLLOW_UPS) != null)
		{
			Matcher f = FOLLOW.matcher(m.group(FOLLOW_UPS));
			while (f.find())
			{
				int n = Integer.parseInt(f.group(FOLLOW_VALUE));
				value = "+".equals(f.group(1)) ? value + n : Math.max(value, n);
			}
		}
		if (value <= 0)
		{
			return;
		}

		String rest = m.group(REST).trim();
		Matcher l = LABEL.matcher(rest);
		String rawLabel = (l.find() ? l.group(1) : rest).trim();
		String label = rawLabel.toLowerCase(Locale.ROOT);
		// "without Nose peg", "with anti-dragon shield": maxes for gear the player may or may not
		// wear. Counting them would alert players who are protected.
		if (label.contains("does not attack") || label.startsWith("with ") || label.contains("without "))
		{
			return;
		}

		Set<AttackStyle> styles;
		if (isDefaultLabel(label))
		{
			styles = defaults;
		}
		else
		{
			styles = stylesOf(label, true);
		}
		for (AttackStyle style : styles)
		{
			if (style == AttackStyle.SPECIAL)
			{
				info.putSpecial(value, specialLabel(rawLabel));
			}
			else
			{
				info.put(style, value);
			}
		}
	}

	/** "special attack" and friends become "Special"; named specials keep their name. */
	private static String specialLabel(String raw)
	{
		String lower = raw.toLowerCase(Locale.ROOT);
		if (raw.isEmpty() || lower.startsWith("spec") || lower.startsWith("typeless"))
		{
			return AttackStyle.SPECIAL.getDisplayName();
		}
		return Character.toUpperCase(raw.charAt(0)) + raw.substring(1);
	}

	private static boolean isDefaultLabel(String label)
	{
		return label.isEmpty() || label.equals("normal") || label.equals("standard") || label.equals("default")
			|| label.startsWith("auto") || label.equals("regular hit") || label.equals("approx")
			|| label.startsWith("x") || label.equals("total") || label.equals("unconfirmed");
	}

	/**
	 * Styles named by an attack_style value or a max_hit label. With {@code specialFallback},
	 * a label naming no normal style is a special; otherwise it names nothing.
	 */
	static Set<AttackStyle> stylesOf(String text, boolean specialFallback)
	{
		String s = text.toLowerCase(Locale.ROOT);
		Set<AttackStyle> out = EnumSet.noneOf(AttackStyle.class);
		boolean typeless = s.contains("typeless");
		if (!typeless && !s.contains("special") && !s.contains("spec "))
		{
			if (s.contains("melee") || s.contains("stab") || s.contains("slash") || s.contains("crush"))
			{
				out.add(AttackStyle.MELEE);
			}
			if (s.contains("ranged") || s.contains("range") || s.contains("missile"))
			{
				out.add(AttackStyle.RANGED);
			}
			if (s.contains("magic") || s.contains("magical"))
			{
				out.add(AttackStyle.MAGIC);
			}
			// "Magical melee"/"Magical ranged" are blocked by Protect from Magic
			if (s.contains("magical"))
			{
				out.remove(AttackStyle.MELEE);
				out.remove(AttackStyle.RANGED);
			}
		}
		if (out.isEmpty() && (specialFallback || typeless || s.contains("dragonfire")))
		{
			out.add(AttackStyle.SPECIAL);
		}
		return out;
	}

	private static List<String> strings(JsonObject row, String key)
	{
		List<String> out = new ArrayList<>();
		JsonElement el = row.get(key);
		if (el == null || el.isJsonNull())
		{
			return out;
		}
		if (el.isJsonArray())
		{
			for (JsonElement e : el.getAsJsonArray())
			{
				if (!e.isJsonNull())
				{
					out.add(e.getAsString());
				}
			}
		}
		else
		{
			out.add(el.getAsString());
		}
		return out;
	}
}

package com.crejaud.chanced;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import org.junit.Test;

public class ChanceCalculatorTest
{
	private static final int GOBLIN_MAX = 2;
	private static final int GOBLIN_HIT = 1;
	private static final int SHARK_HEAL = 20;
	private static final int SAFE_HP = 6;

	private static final int SCURRIUS_MAGIC_MAX = 8;
	private static final int SCURRIUS_ROCKFALL_MAX = 22;
	private static final int ROCKFALL_HIT = 10;
	private static final int LOW_HP = 5;

	private static final int KRIL_MELEE_MAX = 46;
	private static final int KRIL_SMASH_MAX = 49;
	private static final int SMASH_HIT = 30;
	private static final int HP_AFTER_SMASH = 19;

	private static final int CORP_MAGIC_MAX = 60;
	private static final int CORP_HIT = 20;
	private static final int HP_AFTER_CORP = 10;

	private static final int RAT_MAX = 5;
	private static final int BAT_MAX = 4;
	private static final int POISON = 2;

	private static final int SPLIT_ATTACK_MAX = 14;
	private static final int SPLIT_HIT = 3;

	private static final int PERCENT = 100;
	private static final int PKER_ESTIMATE = 50;
	private static final int PKER_HIT = 10;
	private static final int PKER_PRAYED_MAX = PKER_ESTIMATE * ChanceCalculator.PVP_PRAYER_PERCENT / PERCENT;

	private static Attack npc(String source, AttackStyle style, int max, boolean prayed)
	{
		return Attack.builder().source(source).style(style).max(max).prayed(prayed).build();
	}

	private static List<Hit> one(int damage, Attack attack)
	{
		return Collections.singletonList(new Hit(damage, false, attack));
	}

	@Test
	public void maxAtOrAboveHpAndSurvived()
	{
		// GIVEN a goblin that can hit 2 hits for 1
		List<Hit> hits = one(GOBLIN_HIT, npc("Goblin", AttackStyle.MELEE, GOBLIN_MAX, false));

		// WHEN the player is left on its max minus the hit
		Verdict v = ChanceCalculator.evaluate(hits, GOBLIN_MAX - GOBLIN_HIT);

		// THEN it was a chance at the goblin's max
		assertNotNull(v);
		assertEquals("Goblin", v.getSource());
		assertEquals(GOBLIN_MAX, v.getMaxHit());
		assertEquals(GOBLIN_HIT, v.getDamage());
		assertEquals(GOBLIN_MAX, v.getHpBefore());
		assertEquals(GOBLIN_MAX - GOBLIN_HIT, v.getHpAfter());
		assertEquals("Melee", v.getStyle());
	}

	@Test
	public void hpAboveMaxIsNotAChance()
	{
		// GIVEN a goblin that can hit 2 hits for 1
		List<Hit> hits = one(GOBLIN_HIT, npc("Goblin", AttackStyle.MELEE, GOBLIN_MAX, false));

		// WHEN the player had more HP than its max
		Verdict v = ChanceCalculator.evaluate(hits, SAFE_HP);

		// THEN it was never in danger
		assertNull(v);
	}

	@Test
	public void eatingOnTheTickCounts()
	{
		// GIVEN a goblin hits for 1 when the player is on its max of 2
		List<Hit> hits = one(GOBLIN_HIT, npc("Goblin", AttackStyle.MELEE, GOBLIN_MAX, false));

		// WHEN the player eats a shark on the same tick
		Verdict v = ChanceCalculator.evaluate(hits, GOBLIN_MAX - GOBLIN_HIT + SHARK_HEAL);

		// THEN the healed HP counts at the hit, so it was not a chance
		assertNull(v);
	}

	@Test
	public void deathIsNotAChance()
	{
		// GIVEN a hit for the full max
		List<Hit> hits = one(RAT_MAX, npc("Rat", AttackStyle.MELEE, RAT_MAX, false));

		// WHEN the player dies
		Verdict v = ChanceCalculator.evaluate(hits, 0);

		// THEN there is no alert
		assertNull(v);
	}

	@Test
	public void scurriusMagicWrongPrayer()
	{
		// GIVEN Scurrius's magic attack hits 0 without Protect from Magic
		List<Hit> hits = one(0, npc("Scurrius", AttackStyle.MAGIC, SCURRIUS_MAGIC_MAX, false));

		// WHEN the player is on exactly its max
		Verdict v = ChanceCalculator.evaluate(hits, SCURRIUS_MAGIC_MAX);

		// THEN it was a magic chance at its max
		assertNotNull(v);
		assertEquals(SCURRIUS_MAGIC_MAX, v.getMaxHit());
		assertEquals("Magic", v.getStyle());
	}

	@Test
	public void correctPrayerBlocksNpc()
	{
		// GIVEN Scurrius's magic attack hits 0 through Protect from Magic
		List<Hit> hits = one(0, npc("Scurrius", AttackStyle.MAGIC, SCURRIUS_MAGIC_MAX, true));

		// WHEN the player is on exactly its max
		Verdict v = ChanceCalculator.evaluate(hits, SCURRIUS_MAGIC_MAX);

		// THEN the prayer blocked it, so it was not a chance
		assertNull(v);
	}

	@Test
	public void hitThroughPrayerIsTheSpecial()
	{
		// GIVEN K'ril, whose prayer smash ignores Protect from Melee
		Attack smash = Attack.builder().source("K'ril Tsutsaroth").style(AttackStyle.MELEE).max(KRIL_MELEE_MAX)
			.prayed(true).specialMax(KRIL_SMASH_MAX).specialName("Prayer smash").build();

		// WHEN a melee hit goes through the prayer
		Verdict v = ChanceCalculator.evaluate(one(SMASH_HIT, smash), HP_AFTER_SMASH);

		// THEN it counts as the prayer smash
		assertNotNull(v);
		assertEquals(KRIL_SMASH_MAX, v.getMaxHit());
		assertEquals("Prayer smash", v.getStyle());
	}

	@Test
	public void hitThroughPrayerWithoutSpecialCountsDamageDealt()
	{
		// GIVEN an NPC with no special whose attack the right prayer only reduces
		Attack corp = Attack.builder().source("Corporeal Beast").style(AttackStyle.MAGIC).max(CORP_MAGIC_MAX)
			.prayed(true).build();

		// WHEN a hit goes through Protect from Magic at less HP than its max
		Verdict v = ChanceCalculator.evaluate(one(CORP_HIT, corp), HP_AFTER_CORP);

		// THEN only the damage dealt counts, so it was not a chance
		assertNull(v);
	}

	@Test
	public void specialStyle()
	{
		// GIVEN Scurrius's rockfall
		Attack rockfall = Attack.builder().source("Scurrius").style(AttackStyle.SPECIAL).max(SCURRIUS_ROCKFALL_MAX)
			.specialMax(SCURRIUS_ROCKFALL_MAX).specialName("Rockfall").build();

		// WHEN it hits at less HP than its max
		Verdict v = ChanceCalculator.evaluate(one(ROCKFALL_HIT, rockfall), LOW_HP);

		// THEN the alert names the special
		assertNotNull(v);
		assertEquals("Rockfall", v.getStyle());
		assertEquals(SCURRIUS_ROCKFALL_MAX, v.getMaxHit());
	}

	@Test
	public void hitsOnOneTickAreSummed()
	{
		// GIVEN a rat and a bat each hit for 1
		Attack rat = npc("Rat", AttackStyle.MELEE, RAT_MAX, false);
		Attack bat = npc("Bat", AttackStyle.MELEE, BAT_MAX, false);
		// AND poison ticks on the same tick
		List<Hit> hits = Arrays.asList(new Hit(1, false, rat), new Hit(1, false, bat), new Hit(POISON, true, null));

		// WHEN the player is left on 6 HP
		Verdict v = ChanceCalculator.evaluate(hits, SAFE_HP);

		// THEN both maxes plus the poison could have hit, blamed on the biggest threat
		assertNotNull(v);
		assertEquals(RAT_MAX + BAT_MAX + POISON, v.getMaxHit());
		assertEquals("Rat", v.getSource());
	}

	@Test
	public void twoHitsplatsOfOneAttackCountOnce()
	{
		// GIVEN one attack that lands as two hitsplats
		Attack split = npc("Twin", AttackStyle.MAGIC, SPLIT_ATTACK_MAX, false);
		List<Hit> hits = Arrays.asList(new Hit(SPLIT_HIT, false, split), new Hit(SPLIT_HIT, false, split));

		// WHEN the player survives with less HP than its max
		Verdict v = ChanceCalculator.evaluate(hits, SAFE_HP);

		// THEN its max counts once
		assertNotNull(v);
		assertEquals(SPLIT_ATTACK_MAX, v.getMaxHit());
	}

	@Test
	public void playerPrayerReducesByFortyPercent()
	{
		// GIVEN a player's estimated max against the right protection prayer
		Attack pker = Attack.builder().source("Pker").style(AttackStyle.MAGIC).max(PKER_ESTIMATE).prayed(true)
			.player(true).build();

		// WHEN they hit at exactly the prayed max, and at one HP more
		Verdict atMax = ChanceCalculator.evaluate(one(PKER_HIT, pker), PKER_PRAYED_MAX - PKER_HIT);
		Verdict aboveMax = ChanceCalculator.evaluate(one(PKER_HIT, pker), PKER_PRAYED_MAX - PKER_HIT + 1);

		// THEN only the first was a chance, at the prayed max, marked as an estimate
		assertNotNull(atMax);
		assertEquals(PKER_PRAYED_MAX, atMax.getMaxHit());
		assertTrue(atMax.isEstimate());
		assertNull(aboveMax);
	}

	@Test
	public void unexplainedHitAloneIsNotAChance()
	{
		// GIVEN a hit that no attack explains
		List<Hit> hits = one(SPLIT_HIT, null);

		// WHEN the player is left on 1 HP
		Verdict v = ChanceCalculator.evaluate(hits, 1);

		// THEN there is no known max, so no alert
		assertNull(v);
	}

	@Test
	public void damageOverTimeAloneIsNotAChance()
	{
		// GIVEN only a poison tick
		List<Hit> hits = Collections.singletonList(new Hit(POISON, true, null));

		// WHEN the player is left on 1 HP
		Verdict v = ChanceCalculator.evaluate(hits, 1);

		// THEN there is no alert
		assertNull(v);
	}
}

package com.crejaud.chanced;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertSame;
import com.google.gson.JsonObject;
import java.awt.image.BufferedImage;
import org.junit.Test;

public class ChancedEventTest
{
	private static final int WORLD = 302;
	private static final int SCURRIUS_MAGIC_MAX = 8;
	private static final int SCURRIUS_HP = 8;
	private static final ChancedEvent SCURRIUS = new ChancedEvent("Durial321", "Scurrius", "Magic",
		"Protect from Melee", SCURRIUS_MAGIC_MAX, 0, SCURRIUS_HP, SCURRIUS_HP, WORLD, false);

	private static final int GOBLIN_MAX = 2;
	private static final int GOBLIN_HIT = 1;
	private static final int PVP_ESTIMATE = 30;
	private static final int PVP_HIT = 12;
	private static final int PVP_HP = 20;
	private static final int UNKNOWN_HIT = 3;
	private static final int UNKNOWN_HP = 5;

	private static final int EMBED_FIELDS = 6;
	private static final int BASE_DELAY_MS = 2000;
	private static final int TENTH_RETRY = 10;
	private static final long MINUTE_MS = 60_000;
	private static final int SCREEN_WIDTH = 800;
	private static final int SCREEN_HEIGHT = 600;
	private static final int HALF = 50;
	private static final int FULL = 100;

	private static JsonObject embed(JsonObject payload)
	{
		return payload.getAsJsonArray("embeds").get(0).getAsJsonObject();
	}

	@Test
	public void formatsEveryMacro()
	{
		// GIVEN a template with every macro
		String template = "%USERNAME% %SOURCE% %MAXHIT% %DAMAGE% %HP% %HPLEFT% %STYLE% %PRAYER% %WORLD%";

		// WHEN filling it from the Scurrius chance
		String text = SCURRIUS.format(template);

		// THEN every macro is replaced
		assertEquals("Durial321 Scurrius " + SCURRIUS_MAGIC_MAX + " 0 " + SCURRIUS_HP + " " + SCURRIUS_HP
			+ " Magic Protect from Melee " + WORLD, text);
	}

	@Test
	public void defaultChatMessage()
	{
		// GIVEN a goblin chance
		ChancedEvent goblin = new ChancedEvent("Durial321", "Goblin", "Melee", "None", GOBLIN_MAX, GOBLIN_HIT,
			GOBLIN_MAX, GOBLIN_MAX - GOBLIN_HIT, WORLD, false);

		// WHEN filling the default chat template
		String text = goblin.format(ChancedConfig.DEFAULT_CHAT_TEMPLATE);

		// THEN it reads as a message to the player
		assertEquals("You were chanced by Goblin: max hit " + GOBLIN_MAX + " (Melee), hit " + GOBLIN_HIT + ", "
			+ (GOBLIN_MAX - GOBLIN_HIT) + " HP left.", text);
	}

	@Test
	public void estimateAndUnknownMax()
	{
		// GIVEN a PvP estimate and a chance with no known max
		ChancedEvent pvp = new ChancedEvent("Durial321", "Pker", "Magic", "Protect from Magic", PVP_ESTIMATE,
			PVP_HIT, PVP_HP, PVP_HP - PVP_HIT, WORLD, true);
		ChancedEvent unknown = new ChancedEvent("Durial321", "Unknown", "Unknown", "None", -1, UNKNOWN_HIT,
			UNKNOWN_HP, UNKNOWN_HP - UNKNOWN_HIT, WORLD, false);

		// WHEN showing their max hits
		String estimate = pvp.maxHitText();
		String missing = unknown.maxHitText();

		// THEN the estimate gets a ~ and the unknown max a ?
		assertEquals("~" + PVP_ESTIMATE, estimate);
		assertEquals("?", missing);
	}

	@Test
	public void discordEmbed()
	{
		// GIVEN the default Discord template with a screenshot and footer
		String template = ChancedConfig.DEFAULT_DISCORD_TEMPLATE;

		// WHEN building the webhook payload
		JsonObject embed = embed(DiscordNotifier.payload(SCURRIUS, template, true, "Powered by Chanced",
			ChancedConfig.DEFAULT_FOOTER_ICON));

		// THEN the embed has the bolded headline, the detail fields, the screenshot and the footer
		assertEquals("Chanced!", embed.get("title").getAsString());
		assertEquals("**Durial321** was chanced by **Scurrius**", embed.get("description").getAsString());
		assertEquals(EMBED_FIELDS, embed.getAsJsonArray("fields").size());
		assertEquals("attachment://chanced.png", embed.getAsJsonObject("image").get("url").getAsString());
		assertEquals("Powered by Chanced", embed.getAsJsonObject("footer").get("text").getAsString());
		assertEquals(ChancedConfig.DEFAULT_FOOTER_ICON, embed.getAsJsonObject("footer").get("icon_url").getAsString());
	}

	@Test
	public void emptyFooterTextSendsNoFooter()
	{
		// GIVEN blank footer text and no screenshot
		String footerText = " ";

		// WHEN building the webhook payload
		JsonObject embed = embed(DiscordNotifier.payload(SCURRIUS, "x", false, footerText,
			ChancedConfig.DEFAULT_FOOTER_ICON));

		// THEN there is no footer and no image
		assertFalse(embed.has("footer"));
		assertFalse(embed.has("image"));
	}

	@Test
	public void retryBackoffDoublesAndCaps()
	{
		// GIVEN the default base retry delay
		int base = BASE_DELAY_MS;

		// WHEN computing the delay before the first, second and tenth retries
		long first = DiscordNotifier.retryDelayMs(base, 1);
		long second = DiscordNotifier.retryDelayMs(base, 1 + 1);
		long tenth = DiscordNotifier.retryDelayMs(base, TENTH_RETRY);

		// THEN it starts at the base, doubles, and caps at a minute
		assertEquals(BASE_DELAY_MS, first);
		assertEquals(BASE_DELAY_MS + BASE_DELAY_MS, second);
		assertEquals(MINUTE_MS, tenth);
	}

	@Test
	public void screenshotScale()
	{
		// GIVEN an 800x600 screenshot
		BufferedImage image = new BufferedImage(SCREEN_WIDTH, SCREEN_HEIGHT, BufferedImage.TYPE_INT_RGB);

		// WHEN scaling it to 100% and to 50%
		BufferedImage full = DiscordNotifier.scale(image, FULL);
		BufferedImage half = DiscordNotifier.scale(image, HALF);

		// THEN 100% leaves it untouched and 50% halves each side
		assertSame(image, full);
		assertEquals(SCREEN_WIDTH * HALF / FULL, half.getWidth());
		assertEquals(SCREEN_HEIGHT * HALF / FULL, half.getHeight());
	}
}

