package com.crejaud.chanced;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class DragonfireRulesTest
{
	/** The wiki's dragonfire table: chromatic dragons. */
	private static final int CHROMATIC = 50;
	private static final int CHROMATIC_SHIELD = 5;
	private static final int CHROMATIC_PRAYER = 10;
	private static final int CHROMATIC_ANTIFIRE = 35;
	/** The wiki's dragonfire table: King Black Dragon. */
	private static final int KBD = 65;
	private static final int KBD_SHIELD = 15;
	private static final int KBD_PRAYER = 20;
	private static final int KBD_ANTIFIRE = 50;
	private static final int KBD_PRAYER_ANTIFIRE = 5;

	private static DragonfireRules.Protection protection(boolean shield, boolean prayer, boolean antifire,
		boolean superAntifire)
	{
		DragonfireRules.Protection p = new DragonfireRules.Protection();
		p.shield = shield;
		p.prayer = prayer;
		p.antifire = antifire;
		p.superAntifire = superAntifire;
		return p;
	}

	@Test
	public void appliesToDragonfireButNotVorkathsBomb()
	{
		// GIVEN wiki special names
		// WHEN asking whether dragonfire protection applies
		boolean dragonfire = DragonfireRules.applies("Dragonfire");
		boolean bomb = DragonfireRules.applies("Dragonfire Bomb/Special");
		boolean rockfall = DragonfireRules.applies("Rockfall");

		// THEN only regular dragonfire is protected against
		assertTrue(dragonfire);
		assertFalse(bomb);
		assertFalse(rockfall);
	}

	@Test
	public void chromaticTable()
	{
		// GIVEN a chromatic dragon's unprotected dragonfire max
		int max = CHROMATIC;

		// WHEN the player has each combination of protection
		int none = DragonfireRules.max(max, false, protection(false, false, false, false));
		int shield = DragonfireRules.max(max, false, protection(true, false, false, false));
		int prayer = DragonfireRules.max(max, false, protection(false, true, false, false));
		int antifire = DragonfireRules.max(max, false, protection(false, false, true, false));
		int superAntifire = DragonfireRules.max(max, false, protection(false, false, false, true));
		int shieldAndAntifire = DragonfireRules.max(max, false, protection(true, false, true, false));
		int prayerAndAntifire = DragonfireRules.max(max, false, protection(false, true, true, false));

		// THEN the max matches the wiki's table
		assertEquals(CHROMATIC, none);
		assertEquals(CHROMATIC_SHIELD, shield);
		assertEquals(CHROMATIC_PRAYER, prayer);
		assertEquals(CHROMATIC_ANTIFIRE, antifire);
		assertEquals(0, superAntifire);
		assertEquals(0, shieldAndAntifire);
		assertEquals(0, prayerAndAntifire);
	}

	@Test
	public void kingBlackDragonTable()
	{
		// GIVEN the King Black Dragon's unprotected dragonfire max
		int max = KBD;

		// WHEN the player has each combination of protection
		int none = DragonfireRules.max(max, true, protection(false, false, false, false));
		int shield = DragonfireRules.max(max, true, protection(true, false, false, false));
		int prayer = DragonfireRules.max(max, true, protection(false, true, false, false));
		int antifire = DragonfireRules.max(max, true, protection(false, false, true, false));
		int prayerAndAntifire = DragonfireRules.max(max, true, protection(false, true, true, false));
		int shieldAndSuper = DragonfireRules.max(max, true, protection(true, false, false, true));

		// THEN the max matches the wiki's table
		assertEquals(KBD, none);
		assertEquals(KBD_SHIELD, shield);
		assertEquals(KBD_PRAYER, prayer);
		assertEquals(KBD_ANTIFIRE, antifire);
		assertEquals(KBD_PRAYER_ANTIFIRE, prayerAndAntifire);
		assertEquals(0, shieldAndSuper);
	}
}

package com.crejaud.chanced;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import java.util.Collections;
import net.runelite.api.gameval.AnimationID;
import net.runelite.api.gameval.NpcID;
import net.runelite.api.gameval.SpotanimID;
import org.junit.Test;

public class HunllefRulesTest
{
	private static final int CORRUPTED = NpcID.CRYSTAL_HUNLLEF_RANGED_HM;
	private static final int CRYSTALLINE = NpcID.CRYSTAL_HUNLLEF_MAGIC;

	/** Armour points: helm, body and legs tiers summed. */
	private static final int NO_ARMOUR = 0;
	private static final int FULL_T1 = 3;
	private static final int FULL_T2 = 6;
	private static final int FULL_T3 = 9;

	/** The wiki's Corrupted Hunllef max hits with no protection prayer. */
	private static final int UNPRAYED_NONE = 68;
	private static final int UNPRAYED_T1 = 55;
	private static final int UNPRAYED_T2 = 45;
	private static final int UNPRAYED_T3 = 35;
	private static final int[] UNPRAYED = {UNPRAYED_NONE, UNPRAYED_T1, UNPRAYED_T2, UNPRAYED_T3};
	/** One T1 piece, and full T2 plus one T3 piece, fall a third of the way to the next set. */
	private static final int ONE_T1_PIECE = 1;
	private static final int UNPRAYED_ONE_T1_PIECE = 64;
	private static final int T2_PLUS_ONE_T3_PIECE = 7;
	private static final int UNPRAYED_T2_PLUS_ONE_T3_PIECE = 42;
	/** Corrupted Hunllef's max through the right prayer with no armour. */
	private static final int PRAYED_NONE = 16;
	/** Crystalline Hunllef's tornado and floor max in full T3. */
	private static final int CRYSTALLINE_TORNADO_T3 = 10;

	private static final int HIGH_HP = 65;
	private static final int HIT = 26;
	private static final int T3_HIT = 20;
	private static final int PRAYED_HIT = 8;
	private static final int TORNADO_HIT = 6;

	/** Poses the Hunllef plays between attacks, on the tick the previous attack's hit lands. */
	private static final int[] TRANSITIONS = {
		AnimationID.HUNLLEF_ATTACK_TRANSITION_MAGIC, AnimationID.HUNLLEF_ATTACK_TRANSITION_RANGED,
		AnimationID.HUNLLEF_ATTACK_TRANSITION_MAGIC_LOWPRIO, AnimationID.HUNLLEF_ATTACK_TRANSITION_RANGED_LOWPRIO};
	private static final int[] PRAYER_ORBS = {
		SpotanimID.CRYSTAL_HUNLLEF_PRAYER_TRAVEL, SpotanimID.CRYSTAL_HUNLLEF_PRAYER_TRAVEL_HM};

	private static Verdict hit(Attack attack, int damage, int hpBefore)
	{
		return ChanceCalculator.evaluate(Collections.singletonList(new Hit(damage, false, attack)), hpBefore - damage);
	}

	@Test
	public void recognisesBothHunllefs()
	{
		// GIVEN the Corrupted and Crystalline Hunllef NPC ids
		// WHEN checking each
		boolean corrupted = HunllefRules.isHunllef(CORRUPTED);
		boolean crystalline = HunllefRules.isHunllef(CRYSTALLINE);

		// THEN both are the Hunllef
		assertTrue(corrupted);
		assertTrue(crystalline);
	}

	@Test
	public void scalesWithArmour()
	{
		// GIVEN the unprayed max hit table for no armour and full T1, T2 and T3
		int[] table = UNPRAYED;

		// WHEN reading it for full sets and for mixed sets
		int none = HunllefRules.scaled(table, NO_ARMOUR);
		int t1 = HunllefRules.scaled(table, FULL_T1);
		int t2 = HunllefRules.scaled(table, FULL_T2);
		int t3 = HunllefRules.scaled(table, FULL_T3);
		int oneT1Piece = HunllefRules.scaled(table, ONE_T1_PIECE);
		int t2PlusOneT3 = HunllefRules.scaled(table, T2_PLUS_ONE_T3_PIECE);

		// THEN full sets match the wiki and mixed sets fall in between
		assertEquals(UNPRAYED_NONE, none);
		assertEquals(UNPRAYED_T1, t1);
		assertEquals(UNPRAYED_T2, t2);
		assertEquals(UNPRAYED_T3, t3);
		assertEquals(UNPRAYED_ONE_T1_PIECE, oneT1Piece);
		assertEquals(UNPRAYED_T2_PLUS_ONE_T3_PIECE, t2PlusOneT3);
	}

	@Test
	public void unprayedCorruptedUsesArmourTier()
	{
		// GIVEN the Corrupted Hunllef's ranged attack against full T3 armour
		Attack t3 = HunllefRules.attack(CORRUPTED, "Corrupted Hunllef", AttackStyle.RANGED, false, FULL_T3);

		// WHEN it hits at more HP than the T3 max, and at less
		Verdict atHighHp = hit(t3, HIT, HIGH_HP);
		Verdict atLowHp = hit(t3, T3_HIT, UNPRAYED_T3 - 1);

		// THEN only the second is a chance, at the T3 max
		assertNull(atHighHp);
		assertNotNull(atLowHp);
		assertEquals(UNPRAYED_T3, atLowHp.getMaxHit());
	}

	@Test
	public void prayedHitsThroughUpToPrayedMax()
	{
		// GIVEN the Corrupted Hunllef's magic attack through the right prayer, with no armour
		Attack prayed = HunllefRules.attack(CORRUPTED, "Corrupted Hunllef", AttackStyle.MAGIC, true, NO_ARMOUR);

		// WHEN it hits at more HP than the prayed max, and at exactly the prayed max
		Verdict aboveMax = hit(prayed, PRAYED_HIT, PRAYED_NONE + 1);
		Verdict atMax = hit(prayed, PRAYED_HIT, PRAYED_NONE);

		// THEN only the second is a chance, at the prayed max rather than the unprayed one
		assertNull(aboveMax);
		assertNotNull(atMax);
		assertEquals(PRAYED_NONE, atMax.getMaxHit());
		assertEquals("Magic", atMax.getStyle());
	}

	@Test
	public void tornadoesAndFloor()
	{
		// GIVEN a Crystalline Hunllef tornado or floor hit against full T3 armour
		Attack tornado = HunllefRules.attack(CRYSTALLINE, "Crystalline Hunllef", AttackStyle.SPECIAL, false, FULL_T3);

		// WHEN it hits at exactly its max, and at one HP more
		Verdict atMax = hit(tornado, TORNADO_HIT, CRYSTALLINE_TORNADO_T3);
		Verdict aboveMax = hit(tornado, TORNADO_HIT, CRYSTALLINE_TORNADO_T3 + 1);

		// THEN the tornado max is used and only the first is a chance
		assertEquals(CRYSTALLINE_TORNADO_T3, tornado.getMax());
		assertNotNull(atMax);
		assertEquals("Tornado or floor", atMax.getStyle());
		assertNull(aboveMax);
	}

	@Test
	public void prayerDisablingOrbIsMagic()
	{
		// GIVEN the bundled attack style snapshot
		AttackStyleTable table = new AttackStyleTable();

		// WHEN looking up both Hunllefs' prayer-disabling orbs
		// THEN each is a magic attack
		for (int orb : PRAYER_ORBS)
		{
			assertEquals(AttackStyle.MAGIC, table.projectile(orb));
		}
	}

	@Test
	public void styleTransitionsAreNotAttacks()
	{
		// GIVEN the bundled attack style snapshot
		AttackStyleTable table = new AttackStyleTable();

		// WHEN looking up the Hunllef's style transition poses
		// THEN none is an attack a hit could be matched to
		for (int transition : TRANSITIONS)
		{
			assertNull(table.animation(transition));
		}
	}
}

package com.crejaud.chanced;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;
import java.io.BufferedInputStream;
import java.io.InputStream;
import javax.sound.sampled.AudioInputStream;
import javax.sound.sampled.AudioSystem;
import net.runelite.api.SoundEffectVolume;
import org.junit.Test;

public class SoundTest
{
	private static final int FULL = 100;
	private static final int HALF = 50;
	private static final int TOO_LOUD = 250;
	private static final int HALF_VOLUME = SoundEffectVolume.HIGH * HALF / FULL;
	private static final int TENTH = 10;
	private static final float TENTH_GAIN_DB = -20f;
	private static final float DB_TOLERANCE = 0.001f;
	/** An alert sting, not a song. */
	private static final float MAX_SOUND_SECONDS = 2f;

	@Test
	public void volumePercentMapsToClientScale()
	{
		// GIVEN volume percentages from 1% up to out of range
		// WHEN converting each to the client's sound effect volume
		int full = ChancedPlugin.soundVolume(FULL);
		int half = ChancedPlugin.soundVolume(HALF);
		int quietest = ChancedPlugin.soundVolume(1);
		int tooLoud = ChancedPlugin.soundVolume(TOO_LOUD);

		// THEN 100% is the loudest, and out of range values are capped there
		assertEquals(SoundEffectVolume.HIGH, full);
		assertEquals(HALF_VOLUME, half);
		assertEquals(1, quietest);
		assertEquals(SoundEffectVolume.HIGH, tooLoud);
	}

	@Test
	public void volumePercentMapsToFileGain()
	{
		// GIVEN volume percentages for a custom sound file
		// WHEN converting each to decibels of gain
		float full = ChancedPlugin.soundGainDb(FULL);
		float tenth = ChancedPlugin.soundGainDb(TENTH);
		float tooLoud = ChancedPlugin.soundGainDb(TOO_LOUD);

		// THEN 100% plays the file as recorded and each tenfold drop is 20 dB quieter
		assertEquals(0f, full, DB_TOLERANCE);
		assertEquals(TENTH_GAIN_DB, tenth, DB_TOLERANCE);
		assertEquals(0f, tooLoud, DB_TOLERANCE);
	}

	@Test
	public void bundledSoundIsAPlayableWav() throws Exception
	{
		// GIVEN the Chanced sound bundled in the plugin
		InputStream resource = ChancedPlugin.class.getResourceAsStream(ChancedConfig.DEFAULT_SOUND_RESOURCE);
		assertNotNull(resource);

		// WHEN Java's sound system opens it
		try (AudioInputStream audio = AudioSystem.getAudioInputStream(new BufferedInputStream(resource)))
		{
			// THEN it is a short clip
			float seconds = audio.getFrameLength() / audio.getFormat().getFrameRate();
			assertTrue(seconds > 0 && seconds < MAX_SOUND_SECONDS);
		}
	}

	// no-gherkin
	@Test
	public void footerIconIsADirectImageLink()
	{
		assertEquals("https://raw.githubusercontent.com/crejaud/runelite-chanced/master/icon.png",
			ChancedConfig.DEFAULT_FOOTER_ICON);
	}
}

package com.crejaud.chanced;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import java.util.EnumSet;
import java.util.Set;
import org.junit.Test;

public class StyleTest
{
	private static final int SCURRIUS_MELEE_MAX = 13;
	private static final int SCURRIUS_MAGIC_MAX = 8;
	private static final int SCURRIUS_RANGED_MAX = 7;
	private static final int SCURRIUS_ROCKFALL_MAX = 22;

	/** Scurrius in the bundled snapshot: NPC_RAT_BOSS_ATTACK_MELEE_01, _MAGIC_01, VFX_RAT_BOSS_PROJ_MAGIC_01, _RANGED_01. */
	private static final int SCURRIUS_MELEE_ANIMATION = 10692;
	private static final int SCURRIUS_MAGIC_ANIMATION = 10696;
	private static final int SCURRIUS_MAGIC_PROJECTILE = 2640;
	private static final int SCURRIUS_RANGED_PROJECTILE = 2642;
	private static final int AT_LEAST_ANIMATIONS = 1000;

	private static final int STRENGTH_BONUS = 100;
	private static final int WEAPON_ATTACK = 90;
	private static final int RING_STRENGTH = 8;
	private static final int PERCENT = 100;
	private static final int SPEC_MARGIN = 25;
	/** 156 effective strength * (100 + 8 + 64) / 640, rounded. */
	private static final int MELEE_ESTIMATE = 42;
	private static final int MELEE_ESTIMATE_WITH_SPEC = MELEE_ESTIMATE * (PERCENT + SPEC_MARGIN) / PERCENT;
	private static final int MAGIC_ATTACK = 20;
	private static final float MAGIC_DAMAGE_PERCENT = 20f;
	/** A 30 Ice Barrage boosted by 20%. */
	private static final int MAGIC_ESTIMATE = 36;

	private static final int ATTACK_TICK = 100;
	/** Past the two-tick window an NPC's projectile may leave after its animation. */
	private static final int LATE_TICKS = 3;

	private static final Set<AttackStyle> NONE = EnumSet.noneOf(AttackStyle.class);

	private static MonsterInfo scurrius()
	{
		MonsterInfo info = new MonsterInfo("Scurrius");
		info.put(AttackStyle.MELEE, SCURRIUS_MELEE_MAX);
		info.put(AttackStyle.MAGIC, SCURRIUS_MAGIC_MAX);
		info.put(AttackStyle.RANGED, SCURRIUS_RANGED_MAX);
		info.putSpecial(SCURRIUS_ROCKFALL_MAX, "Rockfall");
		return info;
	}

	private static ChancedPlugin.Pending pending(AttackStyle style, boolean projectile)
	{
		ChancedPlugin.Pending p = new ChancedPlugin.Pending();
		p.style = style;
		p.projectile = projectile;
		return p;
	}

	@Test
	public void bundledTableKnowsScurrius()
	{
		// GIVEN the bundled attack style snapshot
		AttackStyleTable table = new AttackStyleTable();

		// WHEN looking up Scurrius's attack animations and projectiles
		AttackHint melee = table.animation(SCURRIUS_MELEE_ANIMATION);
		AttackHint magic = table.animation(SCURRIUS_MAGIC_ANIMATION);
		AttackStyle magicProjectile = table.projectile(SCURRIUS_MAGIC_PROJECTILE);
		AttackStyle rangedProjectile = table.projectile(SCURRIUS_RANGED_PROJECTILE);

		// THEN each has the style its gameval name implies
		assertEquals(AttackHint.MELEE, melee);
		assertEquals(AttackHint.MAGIC, magic);
		assertEquals(AttackStyle.MAGIC, magicProjectile);
		assertEquals(AttackStyle.RANGED, rangedProjectile);
		// AND the table covers the game's attack animations
		assertTrue(table.animationCount() > AT_LEAST_ANIMATIONS);
	}

	@Test
	public void knownStyleWins()
	{
		// GIVEN a Scurrius attack whose animation says melee
		ChancedPlugin.Pending attack = pending(AttackStyle.MELEE, false);

		// WHEN choosing its style while praying melee
		AttackStyle style = ChancedPlugin.chooseStyle(scurrius(), attack, false, EnumSet.of(AttackStyle.MELEE));

		// THEN it stays melee
		assertEquals(AttackStyle.MELEE, style);
	}

	@Test
	public void unknownProjectileTakesWorstUnprayedStyle()
	{
		// GIVEN a Scurrius projectile of unknown style
		ChancedPlugin.Pending projectile = pending(null, true);

		// WHEN choosing its style while praying magic, and while praying nothing
		AttackStyle prayingMagic = ChancedPlugin.chooseStyle(scurrius(), projectile, false,
			EnumSet.of(AttackStyle.MAGIC));
		AttackStyle prayingNothing = ChancedPlugin.chooseStyle(scurrius(), projectile, false, NONE);

		// THEN it is the worst unprayed of ranged and magic
		assertEquals(AttackStyle.RANGED, prayingMagic);
		assertEquals(AttackStyle.MAGIC, prayingNothing);
	}

	@Test
	public void unexplainedHitIsTheSpecial()
	{
		// GIVEN Scurrius, who has a special, and a goblin, who has none
		MonsterInfo goblin = new MonsterInfo("Goblin");
		goblin.put(AttackStyle.MELEE, 1);

		// WHEN each lands a hit with no attack seen
		AttackStyle scurriusStyle = ChancedPlugin.chooseStyle(scurrius(), pending(null, false), true, NONE);
		AttackStyle goblinStyle = ChancedPlugin.chooseStyle(goblin, pending(null, false), true, NONE);

		// THEN Scurrius's hit is the special and the goblin's is its normal style
		assertEquals(AttackStyle.SPECIAL, scurriusStyle);
		assertEquals(AttackStyle.MELEE, goblinStyle);
	}

	@Test
	public void pvpMeleeEstimate()
	{
		// GIVEN a melee weapon and strength bonus visible on another player
		PvpEstimator.Gear gear = new PvpEstimator.Gear();
		gear.str = STRENGTH_BONUS;
		gear.weaponMelee = WEAPON_ATTACK;

		// WHEN estimating with an assumed ring, without and with a spec margin
		AttackStyle style = PvpEstimator.weaponStyle(gear);
		int plain = PvpEstimator.maxHit(gear, AttackStyle.MELEE, RING_STRENGTH, 0, 0);
		int withSpec = PvpEstimator.maxHit(gear, AttackStyle.MELEE, RING_STRENGTH, 0, SPEC_MARGIN);

		// THEN it is a melee estimate, raised by the margin
		assertEquals(AttackStyle.MELEE, style);
		assertEquals(MELEE_ESTIMATE, plain);
		assertEquals(MELEE_ESTIMATE_WITH_SPEC, withSpec);
	}

	@Test
	public void pvpMagicEstimate()
	{
		// GIVEN a magic weapon and magic damage bonus visible on another player
		PvpEstimator.Gear mage = new PvpEstimator.Gear();
		mage.weaponMagic = MAGIC_ATTACK;
		mage.mdmg = MAGIC_DAMAGE_PERCENT;

		// WHEN estimating without a spec margin
		AttackStyle style = PvpEstimator.weaponStyle(mage);
		int max = PvpEstimator.maxHit(mage, AttackStyle.MAGIC, 0, 0, 0);

		// THEN it is an Ice Barrage boosted by the magic damage bonus
		assertEquals(AttackStyle.MAGIC, style);
		assertEquals(MAGIC_ESTIMATE, max);
	}

	@Test
	public void projectileStyleBeatsAnimation()
	{
		// GIVEN an NPC whose animation says ranged and which fired a magic projectile a tick later
		ChancedPlugin.SeenProjectile magic = new ChancedPlugin.SeenProjectile(AttackStyle.MAGIC, ATTACK_TICK + 1);

		// WHEN choosing the style of the attack matched by that animation, or by an unnamed one
		AttackStyle fromRanged = ChancedPlugin.withProjectile(AttackStyle.RANGED, ATTACK_TICK, magic);
		AttackStyle fromUnknown = ChancedPlugin.withProjectile(null, ATTACK_TICK, magic);

		// THEN the projectile's style wins
		assertEquals(AttackStyle.MAGIC, fromRanged);
		assertEquals(AttackStyle.MAGIC, fromUnknown);
	}

	@Test
	public void animationStandsWithoutAProjectileFromThatAttack()
	{
		// GIVEN magic projectiles from before the animation and from well after it
		ChancedPlugin.SeenProjectile earlier = new ChancedPlugin.SeenProjectile(AttackStyle.MAGIC, ATTACK_TICK - 1);
		ChancedPlugin.SeenProjectile later = new ChancedPlugin.SeenProjectile(AttackStyle.MAGIC,
			ATTACK_TICK + LATE_TICKS);

		// WHEN choosing the style of a ranged animation, with no projectile, and of melee and special ones
		AttackStyle none = ChancedPlugin.withProjectile(AttackStyle.RANGED, ATTACK_TICK, null);
		AttackStyle stale = ChancedPlugin.withProjectile(AttackStyle.RANGED, ATTACK_TICK, earlier);
		AttackStyle tooLate = ChancedPlugin.withProjectile(AttackStyle.RANGED, ATTACK_TICK, later);
		AttackStyle melee = ChancedPlugin.withProjectile(AttackStyle.MELEE, ATTACK_TICK, later);
		AttackStyle special = ChancedPlugin.withProjectile(AttackStyle.SPECIAL, ATTACK_TICK + LATE_TICKS, later);

		// THEN the animation's style stands
		assertEquals(AttackStyle.RANGED, none);
		assertEquals(AttackStyle.RANGED, stale);
		assertEquals(AttackStyle.RANGED, tooLate);
		assertEquals(AttackStyle.MELEE, melee);
		assertEquals(AttackStyle.SPECIAL, special);
	}
}

package com.crejaud.chanced;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import com.google.gson.Gson;
import com.google.gson.JsonObject;
import java.util.Arrays;
import java.util.Collections;
import java.util.Map;
import org.junit.Test;

public class WikiMonsterParserTest
{
	private static final int SCURRIUS_MELEE = 13;
	private static final int SCURRIUS_MAGIC = 8;
	private static final int SCURRIUS_RANGED = 7;
	private static final int SCURRIUS_ROCKFALL = 22;
	private static final int SCURRIUS_GROUP_MAGIC = 14;
	private static final int SCURRIUS_GROUP_RANGED = 13;
	private static final int SCURRIUS_GROUP_ROCKFALL = 24;
	private static final int SCURRIUS_ALT_MELEE = 9;
	private static final int SCURRIUS_SOLO_ID = 7222;
	private static final int SCURRIUS_GROUP_ID = 7221;
	private static final int GOBLIN_ID = 3028;
	private static final int GOBLIN_ALT_ID = 3029;
	private static final int GOBLIN_MAX = 1;
	private static final int NON_ATTACKER_ID = 9999;

	private static final int SLASHER_MAX = 36;
	private static final int KRIL_MAGIC = 30;
	private static final int KRIL_MELEE = 46;
	private static final int KRIL_SPECIAL = 49;

	private static final int MULTI_HIT = 7;
	private static final int MULTI_COUNT = 2;
	private static final int SUM_SECOND = 6;
	private static final int CHOICE_LOW = 50;
	private static final int CHOICE_HIGH = 60;
	private static final int RANGE_LOW = 30;
	private static final int RANGE_HIGH = 37;
	private static final int DRAGONFIRE_MIN = 50;

	private static final int AUTO_MAX = 31;
	private static final int LIST_SPECIAL = 45;
	private static final int BASE_MELEE = 22;
	private static final int WHIRLWINDS = 64;
	private static final int KNOCKBACK = 30;
	private static final int BOTH_STYLES = 33;
	private static final int MAGICAL_MELEE = 20;

	private static final int SPECTRE_MAGIC = 14;
	private static final int SPECTRE_UNPROTECTED = 44;
	private static final int SHIELDED = 60;
	private static final int BOOTLESS = 20;

	private static MonsterInfo parse(String attackStyle, String... maxHits)
	{
		return WikiMonsterParser.parse("Test", Arrays.asList(maxHits),
			attackStyle == null ? Collections.emptyList() : Collections.singletonList(attackStyle));
	}

	private static String row(int id, String name, String attackStyle, String... maxHits)
	{
		StringBuilder hits = new StringBuilder();
		for (String h : maxHits)
		{
			hits.append(hits.length() == 0 ? "" : ",").append('"').append(h).append('"');
		}
		return "{\"id\":[\"" + id + "\"],\"max_hit\":[" + hits + "],\"name\":\"" + name
			+ "\",\"attack_style\":[\"" + attackStyle + "\"]}";
	}

	@Test
	public void labelledStyles()
	{
		// GIVEN Scurrius's max hits, one per style plus Rockfall
		String[] maxHits = {SCURRIUS_MELEE + " (Melee)", SCURRIUS_MAGIC + " (Magic)", SCURRIUS_RANGED + " (Ranged)",
			SCURRIUS_ROCKFALL + " (Rockfall)"};

		// WHEN parsing them
		MonsterInfo info = parse("Magic", maxHits);

		// THEN each style has its max and Rockfall is the special
		assertEquals(SCURRIUS_MELEE, info.max(AttackStyle.MELEE));
		assertEquals(SCURRIUS_MAGIC, info.max(AttackStyle.MAGIC));
		assertEquals(SCURRIUS_RANGED, info.max(AttackStyle.RANGED));
		assertEquals(SCURRIUS_ROCKFALL, info.max(AttackStyle.SPECIAL));
		assertEquals("Rockfall", info.getSpecialName());
	}

	@Test
	public void unlabelledUsesAttackStyle()
	{
		// GIVEN an unlabelled max hit on a slash attacker
		String maxHit = String.valueOf(SLASHER_MAX);

		// WHEN parsing it
		MonsterInfo info = parse("Slash", maxHit);

		// THEN it is a melee max only
		assertEquals(SLASHER_MAX, info.max(AttackStyle.MELEE));
		assertFalse(info.has(AttackStyle.MAGIC));
	}

	@Test
	public void specialAttackLabel()
	{
		// GIVEN K'ril's max hits, including "special attack"
		String[] maxHits = {KRIL_MAGIC + " (magic)", KRIL_MELEE + " (melee)", KRIL_SPECIAL + " (special attack)"};

		// WHEN parsing them
		MonsterInfo info = parse("Slash", maxHits);

		// THEN the special is named plainly "Special"
		assertEquals(KRIL_MELEE, info.max(AttackStyle.MELEE));
		assertEquals(KRIL_MAGIC, info.max(AttackStyle.MAGIC));
		assertEquals(KRIL_SPECIAL, info.max(AttackStyle.SPECIAL));
		assertEquals("Special", info.getSpecialName());
	}

	@Test
	public void multipliersSumsAndRanges()
	{
		// GIVEN max hits written as a multiplier, a sum, a choice, a range and a minimum
		// WHEN parsing each
		int multiplier = parse(null, MULTI_HIT + "x" + MULTI_COUNT + " (Magic)").max(AttackStyle.MAGIC);
		int sum = parse("Crush", MULTI_HIT + "+" + SUM_SECOND).max(AttackStyle.MELEE);
		int choice = parse(null, CHOICE_LOW + "/" + CHOICE_HIGH + " (Melee)").max(AttackStyle.MELEE);
		int range = parse(null, RANGE_LOW + "-" + RANGE_HIGH + " (Melee)").max(AttackStyle.MELEE);
		int minimum = parse(null, DRAGONFIRE_MIN + "+ (Dragonfire)").max(AttackStyle.SPECIAL);

		// THEN each gives the most it can hit
		assertEquals(MULTI_HIT * MULTI_COUNT, multiplier);
		assertEquals(MULTI_HIT + SUM_SECOND, sum);
		assertEquals(CHOICE_HIGH, choice);
		assertEquals(RANGE_HIGH, range);
		assertEquals(DRAGONFIRE_MIN, minimum);
	}

	@Test
	public void htmlListsAndRefs()
	{
		// GIVEN max hits in a wiki plainlist and split by <br/>
		String plainlist = "<div class=\"plainlist \" >\n*" + AUTO_MAX + " (auto)\n*" + LIST_SPECIAL + " (special)\n</div>";
		String breaks = BASE_MELEE + " <br/> " + WHIRLWINDS + " (whirlwinds) <br/> " + KNOCKBACK + " (knockback)";

		// WHEN parsing them
		MonsterInfo list = parse(null, plainlist);
		MonsterInfo split = parse("Melee", breaks);

		// THEN every entry is read
		assertEquals(AUTO_MAX, list.max(AttackStyle.MELEE));
		assertEquals(LIST_SPECIAL, list.max(AttackStyle.SPECIAL));
		assertEquals(BASE_MELEE, split.max(AttackStyle.MELEE));
		assertEquals(WHIRLWINDS, split.max(AttackStyle.SPECIAL));
		assertEquals("Whirlwinds", split.getSpecialName());
	}

	@Test
	public void bothStylesInOneLabel()
	{
		// GIVEN one max hit labelled with two styles
		String maxHit = BOTH_STYLES + " (Ranged and Magic)";

		// WHEN parsing it
		MonsterInfo info = parse(null, maxHit);

		// THEN both styles get it and melee does not
		assertEquals(BOTH_STYLES, info.max(AttackStyle.RANGED));
		assertEquals(BOTH_STYLES, info.max(AttackStyle.MAGIC));
		assertFalse(info.has(AttackStyle.MELEE));
	}

	@Test
	public void magicalMeleeIsMagic()
	{
		// GIVEN a "Magical melee" attacker
		String attackStyle = "Magical melee";

		// WHEN parsing its max hit
		MonsterInfo info = parse(attackStyle, String.valueOf(MAGICAL_MELEE));

		// THEN it is magic, which Protect from Magic blocks
		assertEquals(MAGICAL_MELEE, info.max(AttackStyle.MAGIC));
		assertFalse(info.has(AttackStyle.MELEE));
	}

	@Test
	public void skipsGearConditionalMaxes()
	{
		// GIVEN max hits that only apply with or without some gear
		// WHEN parsing them
		MonsterInfo spectre = parse("Magic", String.valueOf(SPECTRE_MAGIC), SPECTRE_UNPROTECTED + " (without Nose peg)");
		MonsterInfo shielded = parse(null, SHIELDED + " (with anti-dragon shield)");
		MonsterInfo boots = parse("Melee", BOOTLESS + " (Ranged/Melee; without insulated boots)");

		// THEN those maxes are ignored
		assertEquals(SPECTRE_MAGIC, spectre.max(AttackStyle.MAGIC));
		assertFalse(spectre.has(AttackStyle.SPECIAL));
		assertFalse(shielded.has(AttackStyle.SPECIAL));
		assertTrue(boots.getMaxHits().isEmpty());
	}

	@Test
	public void skipsNonAttacks()
	{
		// GIVEN max hits that are not numbers to alert on
		// WHEN parsing them
		MonsterInfo passive = parse(null, "0 (Does not attack)");
		MonsterInfo varies = parse(null, "Varies");
		MonsterInfo none = parse(null, "N/A");

		// THEN nothing is recorded
		assertTrue(passive.getMaxHits().isEmpty());
		assertTrue(varies.getMaxHits().isEmpty());
		assertTrue(none.getMaxHits().isEmpty());
	}

	@Test
	public void responseMergesIdsAndRows()
	{
		// GIVEN a bucket response with solo Scurrius, two group Scurrius rows sharing an id
		String json = "{\"bucket\":["
			+ row(SCURRIUS_SOLO_ID, "Scurrius", "Magic", SCURRIUS_MELEE + " (Melee)", SCURRIUS_MAGIC + " (Magic)")
			+ "," + row(SCURRIUS_GROUP_ID, "Scurrius", "Magic", SCURRIUS_MELEE + " (Melee)",
			SCURRIUS_GROUP_MAGIC + " (Magic)", SCURRIUS_GROUP_RANGED + " (Ranged)",
			SCURRIUS_GROUP_ROCKFALL + " (Rockfall)")
			+ "," + row(SCURRIUS_GROUP_ID, "Scurrius", "Melee", SCURRIUS_ALT_MELEE + " (Melee)")
			// AND a goblin listed under two ids, and a non-attacker
			+ ",{\"id\":[\"" + GOBLIN_ID + "\",\"" + GOBLIN_ALT_ID + "\"],\"max_hit\":[\"" + GOBLIN_MAX
			+ "\"],\"name\":\"Goblin\",\"attack_style\":[\"Crush\"]}"
			+ "," + row(NON_ATTACKER_ID, "Nothing", "None", "N/A")
			+ "]}";

		// WHEN parsing it
		Map<Integer, MonsterInfo> out = WikiMonsterParser.parseResponse(new Gson().fromJson(json, JsonObject.class));

		// THEN each id has its max hits
		assertNotNull(out.get(SCURRIUS_SOLO_ID));
		assertEquals(SCURRIUS_MAGIC, out.get(SCURRIUS_SOLO_ID).max(AttackStyle.MAGIC));
		// AND the higher value wins for an id listed twice
		assertEquals(SCURRIUS_MELEE, out.get(SCURRIUS_GROUP_ID).max(AttackStyle.MELEE));
		assertEquals(SCURRIUS_GROUP_MAGIC, out.get(SCURRIUS_GROUP_ID).max(AttackStyle.MAGIC));
		// AND every listed id is covered, but a non-attacker is not
		assertEquals(GOBLIN_MAX, out.get(GOBLIN_ALT_ID).max(AttackStyle.MELEE));
		assertNull(out.get(NON_ATTACKER_ID));
	}
}
